#!/usr/bin/env python3
"""Fingerprint mapproxy/environment.yml, and stamp the fingerprint into the lock files.

Dockerfile.mapproxy installs the exact packages listed in
mapproxy/conda-linux-64.lock and mapproxy/conda-linux-aarch64.lock, which
scripts/lock-mapproxy.sh generates from mapproxy/environment.yml. Each lock
file records a fingerprint of the environment.yml it came from, so
check-sync.py can tell when someone edits the dependencies and forgets to
regenerate: the image would keep shipping the old packages while the file that
reads as their source says otherwise.

The fingerprint covers the channels and the dependency specs, not the file's
bytes. A comment or a reordering therefore doesn't count as a change, which
matters because regenerating re-resolves every package to whatever conda-forge
has that day -- something a comment edit must never force.

Run inside the micromamba image by scripts/lock-mapproxy.sh (PyYAML comes with
conda-lock), and imported by check-sync.py:

    mapproxy_lock.py hash  ENVIRONMENT_YML
    mapproxy_lock.py stamp ENVIRONMENT_YML LOCK_FILE...
"""

from __future__ import annotations

import hashlib
import json
import sys
from pathlib import Path

import yaml

STAMP_PREFIX = "# environment.yml spec sha256: "
GENERATED_BY = "# Generated by scripts/lock-mapproxy.sh from mapproxy/environment.yml. Do not edit."


def spec_hash(environment_yml: Path) -> str:
    """SHA-256 of the channels and (sorted) dependency specs in environment.yml."""
    spec = yaml.safe_load(environment_yml.read_text(encoding="utf-8"))
    canonical = {
        "channels": spec.get("channels", []),
        "dependencies": sorted(spec.get("dependencies", [])),
    }
    return hashlib.sha256(json.dumps(canonical, sort_keys=True).encode()).hexdigest()


def stamped_hash(lock_file: Path) -> str | None:
    """The fingerprint recorded in a lock file, or None if it has none."""
    for line in lock_file.read_text(encoding="utf-8").splitlines():
        if line.startswith(STAMP_PREFIX):
            return line.removeprefix(STAMP_PREFIX).strip()
    return None


def stamp(lock_file: Path, digest: str) -> None:
    """Put the fingerprint at the top of a lock file, replacing any earlier stamp.
    micromamba skips `#` lines in an explicit lock file, so this doesn't affect installs."""
    kept = [
        line
        for line in lock_file.read_text(encoding="utf-8").splitlines()
        if line != GENERATED_BY and not line.startswith(STAMP_PREFIX)
    ]
    lock_file.write_text("\n".join([GENERATED_BY, STAMP_PREFIX + digest, *kept]) + "\n", encoding="utf-8")


def main(argv: list[str]) -> int:
    if len(argv) == 3 and argv[1] == "hash":
        print(spec_hash(Path(argv[2])))
        return 0
    if len(argv) >= 4 and argv[1] == "stamp":
        digest = spec_hash(Path(argv[2]))
        for lock_file in argv[3:]:
            stamp(Path(lock_file), digest)
        return 0
    print(__doc__, file=sys.stderr)
    return 2


if __name__ == "__main__":
    sys.exit(main(sys.argv))
